(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.28)*18 + Math.cos(y*0.013-t*0.22)*12 + Math.sin((x+y)*0.009+t*0.15)*8;
  const w1y = Math.cos(y*0.02-t*0.24)*18 + Math.sin(x*0.016+t*0.32)*12 + Math.cos((x-y)*0.01-t*0.18)*8;
  const w2x = Math.sin(w1x*0.025+t*0.45)*10 + Math.cos(w1y*0.02-t*0.35)*7;
  const w2y = Math.cos(w1y*0.022+t*0.4)*10 + Math.sin(w1x*0.018-t*0.42)*7;
  const sx = x + w1x + w2x, sy = y + w1y + w2y;
  const src = [
    [160+Math.sin(t*0.55)*110, 70+Math.cos(t*0.38)*55, 0.075, 2.1, 0.6],
    [320+Math.cos(t*0.48)*100, 160+Math.sin(t*0.65)*55, 0.095, 1.8, 0.8],
    [240+Math.sin(t*0.32+2)*150, 110+Math.cos(t*0.52+1)*95, 0.055, 2.4, 0.5],
    [110+Math.cos(t*0.75+1)*85, 185+Math.sin(t*0.58+3)*65, 0.11, 1.6, 0.9],
    [370+Math.sin(t*0.42+4)*95, 55+Math.cos(t*0.85+2)*75, 0.065, 2.7, 0.4],
    [240+Math.cos(t*0.33+5)*130, 205+Math.sin(t*0.5)*85, 0.085, 2.0, 0.7],
    [60+Math.sin(t*0.6+3)*70, 40+Math.cos(t*0.7+1)*50, 0.13, 1.4, 1.0],
    [420+Math.cos(t*0.45+2)*60, 200+Math.sin(t*0.55+4)*55, 0.1, 1.9, 0.55]
  ];
  let aS=0, iS=0, cS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const a = Math.sin(d*f-t*sp), inh = Math.sin(d*f*0.7+t*sp*0.6+1.5);
    const coup = Math.sin(d*f*0.5-t*sp*0.3+2.8)*Math.cos(d*f*0.3+t*sp*0.9);
    aS += a*w; iS += inh*w; cS += coup*w;
  }
  const tw = 5.8;
  const act=aS/tw, inh=iS/tw, coup=cS/tw;
  const bg = (Math.sin(sx*0.035+sy*0.022+t*0.75)+Math.sin(sx*0.028-sy*0.038+t*1.05))/2
    + Math.sin((sx+sy)*0.11+t*2.3)*0.2 + Math.sin((sx-sy)*0.095-t*1.8)*0.2
    + Math.sin(sx*0.06+t*1.5)*Math.sin(sy*0.05-t*1.2)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
