  const reaction = Math.tanh((act - inh*0.65 + bg*0.25 + spiral + coup*0.35 + lapA*0.15)*2.0);
  const cell = Math.tanh((Math.sin(sx*0.14)*Math.sin(sy*0.14)+Math.sin((sx+sy)*0.09+t)*0.5+Math.sin(sx*0.08-sy*0.11+t*0.7)*0.3)*1.4)*0.25;
  const micro = Math.sin(sx*0.35+sy*0.28+t*3)*Math.sin(sx*0.22-sy*0.31-t*2.5)*0.08;
  const pulse = 0.92+Math.sin(t*0.8)*0.08;
  const blend = (reaction*0.65+cell*0.2+micro)*pulse, v = blend*0.5+0.5;
  const vig = 1.0-Math.sqrt(((x-cx)/240)**2+((y-cy)/120)**2)*0.15;
  const pal = [[5,12,52],[10,42,82],[12,75,105],[18,120,130],[45,155,135],[130,175,100],[195,175,70],[220,145,55],[210,100,60],[175,60,65],[120,35,75],[60,20,60],[5,12,52]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.82+Math.sin(reaction*Math.PI)*0.18;
  const edge=Math.abs(reaction)>0.72?1.12:Math.abs(reaction)>0.5?1.04:1.0;
  const glow=Math.max(0,reaction-0.3)*0.25;
  return [
    Math.min(255,Math.max(0,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*60)*vig))|0,
    Math.min(255,Math.max(0,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*40)*vig))|0,
    Math.min(255,Math.max(0,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*30)*vig))|0
  ];
}
